INSERT INTO benefit_items_import VALUES
  ('fubon', '富邦人壽日安心住院醫療定額健康保險附約', 1, '住院醫療', '住院醫療保險金', '日額 × 天數', '第八條被保險人於本附約有效期間內因疾病或傷害，而於醫院接受住院診療者，本公司按下列約定給付「住院醫療保險金」：一、被保險人同一次住院診療在三十日（含）以內者，本公司按住院醫療保險金日額乘以被保險人實際住院日數（含出院及入院當日），給付「住院醫療保險金」。'),
  ('fubon', '富邦人壽日安心住院醫療定額健康保險附約', 2, '住院看護', '住院看護保險金', '日額 × 50% × 天數', '第九條被保險人於本附約有效期間內因疾病或傷害，而於醫院接受住院診療者，本公司除依第八條約定給付「住院醫療保險金」外，另按住院醫療保險金日額的百分之五十，乘以依第八條所給付之日數計算所得之金額給付「住院看護保險金」。'),
  ('fubon', '富邦人壽日安心住院醫療定額健康保險附約', 3, '出院療養', '出院後療養保險金', '日額 × 50% × 天數', '第十條被保險人於本附約有效樣期間內因疾病或傷害，入住醫院後出院者，本公司除依第八條約定給付「住院醫療保險金」外，另按住院醫療保險金日額的百分之五十，乘以依第八條所給付之日數計算所得之金額給付「出院後療養保險金」。'),
  ('fubon', '富邦人壽日安心住院醫療定額健康保險附約', 4, '加護病房醫療', '加護病房醫療保險金', '日額 × 2', '第十一條被保險人於本附約有效期間內因疾病或傷害，而於醫院之加護病房住院診療者，本公司除依第八條約定給付「住院醫療保險金」外，另按其實際入住加護病房日數，乘以住院醫療保險金日額的二倍給付「加護病房醫療保險金」。'),
  ('fubon', '富邦人壽日安心住院醫療定額健康保險附約', 5, '燒燙傷中心醫療', '燒燙傷中心醫療保險金', '日額 × 3', '第十二條被保險人於本附約有效期間內因傷害，而於醫院之燒燙傷中心住院診療者，本公司除依第八條約定給付「住院醫療保險金」外，另按其實際入住燒燙傷中心日數，乘以住院醫療保險金日額的三倍給付「燒燙傷中心醫療保險金」。'),
  ('fubon', '富邦人壽日安心住院醫療定額健康保險附約', 6, '住院前後門診', '住院前後門診保險金', '日額 × 50% × 天數', '第十三條被保險人於本附約有效期間內因疾病或傷害，經醫師診斷而住院診療者，於住院前二週內及出院後二週內，因診療同一事故為直接目的而於醫院接受門診診療者，本公司按住院醫療保險金日額的百分之五十，乘以實際門診日數（不論被保險人同一日之門診次數為一次或多次，均以一日計），給付「住院前後門診保險金」。'),
  ('fubon', '富邦人壽日安心住院醫療定額健康保險附約', 7, '住院手術醫療', '住院手術醫療保險金', '日額 × 30', '第十四條被保險人於本附約有效期間內因疾病或傷害，經醫師診斷必須住院接受附表一所列手術診療且已接受該手術者，本公司按住院醫療保險金日額的三十倍乘以附表一所列該項手術所對應之給付百分比率，給付「住院手術醫療保險金」。'),
  ('fubon', '富邦人壽日安心住院醫療定額健康保險附約', 8, '住院手術看護', '住院手術看護保險金', '日額 × 5', '第十五條被保險人符合受領第十四條「住院手術醫療保險金」之條件者，本公司除依約定給付「住院手術醫療保險金」外，另按住院醫療保險金日額的五倍乘以計算「住院手術醫療保險金」同一百分比率所得之金額，給付「住院手術看護保險金」。'),
  ('fubon', '富邦人壽日安心住院醫療定額健康保險附約', 9, '門診手術醫療', '門診手術醫療保險金', NULL, '第十六條被保險人於本附約有效期間內因疾病或傷害，經醫師診斷必須於門診接受附表一所列手術診療且已接受該手術者，本公司按住院醫療保險金日額給付「門診手術醫療保險金」。'),
  ('fubon', '富邦人壽日安心住院醫療定額健康保險附約', 10, '特定重大疾病', '特定重大疾病保險金', '日額 × 100', '第十七條被保險人於本附約有效期間內因疾病或傷害，經醫院醫師診斷確定罹患第二條第七款約定之特定重大疾病且已接受手術者，樣每次移植手術本公司按住院醫療保險金日額的一百倍給付「特定重大疾病保險金」。'),
  ('fubon', '富邦人壽日安心住院醫療定額健康保險附約', 11, '健康增值', '健康增值保險金', NULL, '第十八條被保險人依第八條至第十七條之約定申請保險金時，以下列各款日期中最接近本次保險事故發生日起算，達二年(含)以上未曾發生本附約約定之保險事故之一者，本公司按本次保險事故所得受領之保險金總額乘以百分之二十，給付「健康增值保險金」：一、本附約生效日。'),
  ('fubon', '富邦人壽癌無憂防癌定期健康保險', 1, '罹患癌症（初期）或癌症（輕度）', '罹患癌症(初期)或癌症(輕度)保險金', NULL, '第十四條被保險人於等待期間屆滿後或復效日起之本契約有效期間內，始經病理檢驗確定罹患第二條約定之「癌症(初期)或癌症(輕度)」者，本公司按首次醫院醫師診斷確定日之保單年度對應下表所列之給付金額，給付「罹患癌症(初期)或癌症(輕度)保險金」，並以給付一次為限，同時或先後罹患癌症(初期)及癌症(輕度)者亦同。'),
  ('fubon', '富邦人壽癌無憂防癌定期健康保險', 2, '罹患癌症（重度）', '罹患癌症(重度)保險金', NULL, '第十五條被保險人於等待期間屆滿後或復效日起之本契約有效期間內，始經病理檢驗確定罹患第二條約定之「癌症(重度)」者，本公司按首次醫院醫師診斷確定日之保單年度對應下表所列之給付金額，給付「罹患癌症(重度)保險金」後，本契約效力即行終止。'),
  ('fubon', '富邦人壽癌無憂防癌定期健康保險', 3, '滿期', '滿期保險金', NULL, '本公司依第二十條約定給付「滿期保險金」者，不再負第十五條至第十七條約定保險金給付之責。'),
  ('fubon', '富邦人壽癌無憂防癌定期健康保險', 4, '身故', '身故保險金或喪葬費用保險金', NULL, '第二十八條有下列情形之一者，本公司不負給付「身故保險金或喪葬費用保險金」及「完全失能豁免保險費」的責任：一、要保人故意致被保險人於死。'),
  ('fubon', '富邦人壽癌無憂防癌定期健康保險', 5, '意外傷害身故保險金或喪葬費用', '意外傷害身故保險金或喪葬費用保險金', NULL, '第二十九條被保險人因下列原因致成死亡或失能時，本公司不負給付「意外傷害身故保險金或喪葬費用保險金」及「二至六級意外失能豁免保險費」的責任：一、要保人、被保險人的故意行為。'),
  ('fubon', '富邦人壽醫靠安心重大傷病定期健康保險', 1, '重大傷病', '重大傷病保險金', NULL, '第十五條被保險人於等待期間屆滿後、復效日或續保日起之本契約有效期間內，經醫院醫師診斷，確認首次罹患第二條約定重大傷病範圍所列傷病之一，且符合下列兩項情形之一者，本公司按下表約定給付「重大傷病保險金」後，本契約效力即行終止：一、已依中央衛生主管機關所公告實施之「全民健康保險保險對象免自行負擔費用辦法」規定，取得全民健康保險保險人核發之重大傷病證明者，該證明文'),
  ('fubon', '富邦人壽醫靠安心重大傷病定期健康保險', 2, '特定重大傷病', '特定重大傷病保險金', '保額 × 20%', '第十六條被保險人於本契約第二保單年度起或續保日起之有效期間內，經醫院醫師診斷，確認首次罹患第二條約定之重大傷病之一，而得受領第十五條約定之「重大傷病保險金」，且該項重大傷病亦同時符合第二條約定之「特定重大傷病」者，本公司除給付「重大傷病保險金」外，另按罹患特定重大傷病時之保險金額的20%給付「特定重大傷病保險金」後，本契約效力即行終止。'),
  ('fubon', '富邦人壽醫靠安心重大傷病定期健康保險', 3, '特定重大疾病', '特定重大疾病保險金', '取較高：保費 × 1.06／保額 × 1', '第十七條被保險人於等待期間屆滿後、復效日或續保日起之本契約有效期間內，經醫院醫師診斷，確認罹患第二條約定特定重大疾病項目之一者，本公司按下列二者之最大值給付「特定重大疾病保險金」後，本契約效力即行終止：一、罹患特定重大疾病時之保險金額（以萬元為單位），乘以本保險年繳方式之標準體保險費費率，再乘以保險期間屆滿前已經過之實際繳費年度數（未滿一年者以一年計算），再乘以一點零六倍。但續保者，實際繳費年度數（未滿一年者以一年計算）應自續保時重新起算。二、罹患特定重大疾病時之保險金額。被保險人於本契約有效期間內，不論同時或先後罹患二項特定重大疾病，本公司僅對其中一項特定重大疾病負給付「特定重大疾病保險金」之責任。若係同項特定重大疾病發生二次以上者，本公司僅對其中一次特定重大疾病負給付「特定重大疾病保險'),
  ('fubon', '富邦人壽醫靠安心重大傷病定期健康保險', 4, '特定傷病', '特定傷病保險金', '取較高：保費 × 1.06／保額 × 1', '第十八條被保險人於等待期間屆滿後、復效日或續保日起之本契約有效期間內，經醫院醫師診斷，確認罹患第二條約定特定傷病項目之一者，本公司按下列二者之最大值給付「特定傷病保險金」後，本契約效力即行終止：一、罹患特定傷病時之保險金額(以萬元為單位)，乘以本保險年繳方式之標準體保險費費率，再乘以保險期間屆滿前已經過之實際繳費年度數(未滿一年者以一年計算)，再乘以一點零六倍。但續保者，實際繳費年度數(未滿一年者以一年計算)應自續保時重新起算。二、罹患特定傷病時之保險金額。被保險人於本契約有效期間內，不論同時或先後罹患二項特定傷病，本公司僅對其中一項特定傷病負給付「特定傷病保險金」之責任。若係同項特定傷病發生二次以上者，本公司僅對其中一次特定傷病負給付「特定傷病保險金」之責任。【分期定期保險金給付'),
  ('fubon', '富邦人壽醫靠安心重大傷病定期健康保險', 5, '身故', '喪葬費用保險金', NULL, '前項情形，如要保人向二家(含)以上保險公司投保，或向同一保險公司投保數個保險契(附)約，且其投保之喪葬費用保險金額合計超過前項所定之限額者，本公司於所承保之喪葬費用金額範圍內，依各要保書所載之要保時間先後，依約給付「喪葬費用保險金」至前項喪葬費用額度上限為止，如有二家以上保險公司之保險契約要保時間相同或無法區分其要保時間之先後者，各該保險公司應依其喪葬費用保險金額與扣除要保時間在先之保險公'),
  ('fubon', '富邦人壽醫靠安心重大傷病定期健康保險', 6, '完全失能', '完全失能保險金', '取較高：保費 × 1.06／保額 × 1', '第二十一條被保險人於本契約有效期間內致成附表二所列完全失能程度之一者，本公司按下列二者之最大值給付「完全失能保險金」後，本契約效力即行終止：一、完全失能診斷確定時之保險金額（以萬元為單位），乘以本保險年繳方式之標準體保險費費率，再乘以保險期間屆滿前已經過之實際繳費年度數（未滿一年者以一年計算），再乘以一點零六倍。但續保者，實際繳費年度數（未滿一年者以一年計算）應自續保時重新起算。二、完全失能診斷確定時之保險金額。【保險範圍：無理賠回饋保險金的給付】第二十二條被保險人於本契約有效期間內，未曾發生第十五條至第十八條及第二十條至第二十一條所約定之任一項保險事故且保險期間屆滿仍生存者，本公司按年繳保險費總和的10%給付「無理賠回饋保險金'),
  ('fubon', '富邦人壽醫靠安心重大傷病定期健康保險', 7, '無理賠回饋', '無理賠回饋保險金', '依已繳保費計算（看原文）', '第二十二條被保險人於本契約有效期間內，未曾發生第十五條至第十八條及第二十條至第二十一條所約定之任一項保險事故且保險期間屆滿仍生存者，本公司按年繳保險費總和的10%給付「無理賠回饋保險金」。'),
  ('fubon', '富邦人壽金安守護終身健康保險', 1, '手術醫療', '手術醫療保險金', '保額 × 附表倍數', '第十三條被保險人於本契約有效期間內因疾病或傷害，經醫師診斷須接受附表一所列手術治療且已接受該手術者，本公司按保險金額乘以附表一所列該項手術項目所對應的給付倍數後計算所得之金額，給付「手術醫療保險金」。'),
  ('fubon', '富邦人壽金安守護終身健康保險', 2, '特定處置項目', '特定處置項目保險金', '保額 × 附表倍數', '第十四條被保險人於本契約有效期間內因疾病或傷害，經醫師診斷必須接受附表二所列之特定處置項目治療且已接受該治療者，本公司按保險金額乘以附表二所列該項特定處置項目所對應的給付倍數後計算所得之金額，給付「特定處置項目保險金」。'),
  ('fubon', '富邦人壽金安守護終身健康保險', 3, '身故', '身故保險金', NULL, '第十八條被保險人於本契約有效期間內身故者，本公司依當年度保險金額給付「身故保險金」後，本契約效力即行終止。'),
  ('fubon', '富邦人壽金安守護終身健康保險', 4, '祝壽', '祝壽保險金', NULL, '第十九條被保險人於本契約有效期間內且在保險年齡屆滿九十九歲仍生存者，本公司依當年度保險金額給付「祝壽保險金」後，本契約效力即行終止。'),
  ('fubon', '富邦人壽愛實在一年期防癌醫療健康保險附約', 1, '癌症住院醫療費用', '癌症住院醫療費用保險金', NULL, '並因癌症或直接因癌症本身所引起之併發症，經醫院醫師診斷須於醫院住院接受診療，而以全民健康保險之保險對象身分於醫院接受住院診療者，同一次住院期間，本公司按被保險人住院期間內所發生，且依全民健康保險規定其保險對象應自行負擔及不屬全民健康保險給付範圍之本條第三項各款實際支出之癌症住院醫療費用，於扣除下列二者之最大值後之餘額，給付癌症住院醫療費用保險金。'),
  ('fubon', '富邦人壽愛實在一年期防癌醫療健康保險附約', 2, '癌症門診醫療費用', '癌症門診醫療費用保險金', NULL, '症，並因癌症或直接因癌症本身所引起之併發症，經醫院醫師診斷須於醫院門診接受診療，而以全民健康保險之保險對象身分於醫院接受門診診療者，同一日內門診，本公司按被保險人同一日內所發生，且依全民健康保險規定其保險對象應自行負擔及不屬全民健康保險給付範圍之本條第三項各款實際支出之癌症門診醫療費用，於扣除下列二者之最大值後之餘額，給付癌症門診醫療費用保險金。'),
  ('fubon', '富邦人壽愛實在一年期防癌醫療健康保險附約', 3, '該部分癌症門診醫療費用', '該部分癌症門診醫療費用保險金', NULL, '若被保險人該日癌症門診醫療費用已依第八條給付後，本公司不再給付該部分癌症門診醫療費用保險金。'),
  ('fubon', '富邦人壽樂齡金安定期健康保險', 1, '身故', '身故保險金', NULL, '第二十一條被保險人於本契約有效期間內身故者，本公司依當年度保險金額給付身故保險金後，本契約效力即行終止。'),
  ('fubon', '富邦人壽樂齡金安定期健康保險', 2, '住院醫療', '住院醫療保險金', '日額 × 天數', '第十三條被保險人於本契約有效期間內因疾病或傷害，而於醫院接受住院診療者，本公司按住院醫療保險金日額乘以被保險人實際住院日數（含出院及入院當日），給付住院醫療保險金。'),
  ('fubon', '富邦人壽樂齡金安定期健康保險', 3, '加護病房或燒燙傷病房醫療', '加護病房或燒燙傷病房醫療保險金', '日額 × 5', '第十四條被保險人於本契約有效期間內因疾病或傷害，而於醫院之加護病房或燒燙傷病房接受住院診療者，本公司除依第十三條約定給付住院醫療保險金外，另按其實際入住加護病房或燒燙傷病房日數，乘以住院醫療保險金日額的五倍，給付加護病房或燒燙傷病房醫療保險金。'),
  ('fubon', '富邦人壽樂齡金安定期健康保險', 4, '意外傷害住院醫療', '意外傷害住院醫療保險金', '日額 × 天數', '第十五條被保險人於本契約有效期間內，因遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內，而於醫院接受住院治療者，本公司除依第十三條約定給付住院醫療保險金外，另按其致成意外傷害事故當時之住院醫療保險金日額，乘以被保險人該次實際住院日數（含出院及入院當日），給付意外傷害住院醫療保險金。'),
  ('fubon', '富邦人壽樂齡金安定期健康保險', 5, '住院手術醫療', '住院手術醫療保險金', '日額 × 附表倍數', '第十六條被保險人於本契約有效期間內因疾病或傷害，經醫師診斷必須住院接受附表一所列手術治療且已接受該手術者，本公司依其接受手術之保單年度，按下列約定給付住院手術醫療保險金：HJJ11403106/36商品代號：HJJ一、第一保單年度：按住院醫療保險金日額的50%，乘以附表一所列該項手術所對應之給付倍數計算所得之金額。二、第二保單年度起之各保單年度內：按住院醫療保險金日額，乘以附表一所列該項手術所對應之給付倍數計算所得之金額。前項情形，被保險人於同一次手術中，在同一手術位置接受二項（含）以上手術項目時，本公司僅按最高給付倍數的一項手術項目給付住院手術醫療保險金。被保險人所接受的手術，若不在附表一所列手術項目，但屬於「全民健康保險醫療服務給付項目及支付標準」第二部第二章第七節手術項目或'),
  ('fubon', '富邦人壽樂齡金安定期健康保險', 6, '門診手術醫療', '門診手術醫療保險金', '日額 × 附表倍數', '第十七條被保險人於本契約有效期間內因疾病或傷害，經醫師診斷必須於醫院或診所以門診方式接受附表一所列手術治療且已接受該手術者，本公司依其接受手術之保單年度，按下列約定給付門診手術醫療保險金：一、第一保單年度：按住院醫療保險金日額的50%，乘以附表一所列該項手術所對應之給付倍數計算所得之金額。二、第二保單年度起之各保單年度內：按住院醫療保險金日額，乘以附表一所列該項手術所對應之給付倍數計算所得之金額。前項情形，被保險人於同一次手術中，在同一手術位置接受二項（含）以上手術項目時，本公司僅按最高給付倍數的一項手術項目給付門診手術醫療保險金。被保險人所接受的手術，若不在附表一所列手術項目，但屬於「全民健康保險醫療服務給付項目及支付標準」第二部第二章第七節手術項目或第三部第三章第四節第三項開刀房手術所列舉之手'),
  ('fubon', '富邦人壽樂齡金安定期健康保險', 7, '特定處置項目', '特定處置項目保險金', '日額 × 附表倍數', '第十八條被保險人於本契約有效期間內因疾病或傷害，經醫師診斷必須接受附表二所列之特定處置項目治療且已接受該治療者，本公司依其接受治療之保單年度，按下列約定給付特定處置項目保險金：一、第一保單年度內：按住院醫療保險金日額的50%，乘以附表二所列該項特定處置所對應之給付倍數計算所得之金額。二、第二保單年度起之各保單年度內：按住院醫療保險金日額，乘以附表二所列該項特定處置所對應之給付倍數計算所得之金額。如被保險人所接受之處置治療，未載明於附表二所列之特定處置項目者，本公司將不負給付特定處置項目保險金之責任。被保險人因同一傷害或同一疾病或其引致之併發症而需接受同項二次（含）或二項（含）以上相同之特定處置治療時，自前次處置治療接受當日起十四日內（含）之所有處置治療，皆視為同一次處置治療，本公司僅給'),
  ('fubon', '富邦人壽樂齡金安定期健康保險', 8, '一次特定處置項目', '一次特定處置項目保險金', NULL, '被保險人因同一傷害或同一疾病或其引致之併發症而需接受同項二次（含）或二項（含）以上相同之特定處置治療時，自前次處置治療接受當日起十四日內（含）之所有處置治療，皆視為同一次處置治療，本公司僅給付一次特定處置項目保險金。'),
  ('fubon', '富邦人壽金給力防癌健康保險', 1, '罹患癌症', '罹患癌症保險金', NULL, '第十九條本公司依第十四條第一項第三款約定給付「罹患癌症保險金」者，除應同時給付第十五條約定之「癌症（重度）安養保險金」外，不再負本契約其他各項保險金給付之責。'),
  ('fubon', '富邦人壽金給力防癌健康保險', 2, '癌症（重度）安養', '癌症（重度）安養保險金', '保額 × 2%', '第十五條被保險人於等待期間屆滿後或復效日起之本契約有效期間內，經醫院醫師診斷確定罹患「癌症（重度）」且符合受領罹患癌症保險金之條件者，本公司於「癌症（重度）」診斷確定日後之每一週月日，依診斷確定當時保險金額的2％給付「癌症（重度）安養保險金」，共給付二十四個月（不論被保險人生存與否）。'),
  ('fubon', '富邦人壽金給力防癌健康保險', 3, '身故', '身故保險金或喪葬費用保險金', NULL, '第二十五條有下列情形之一者，本公司不負給付「身故保險金或喪葬費用保險金」的責任：一、要保人故意致被保險人於死。'),
  ('fubon', '富邦人壽卡好康重大傷病終身健康保險', 1, '重大傷病', '重大傷病保險金', NULL, '第十三條被保險人於等待期間屆滿後或復效日起之本契約有效期間內，經醫院醫師診斷，確認首次罹患第二條約定重大傷病範圍所列傷病之一，且符合下列兩項情形之一者，本公司按下表約定給付「重大傷病保險金」後，本契約效力即行終止：一、已依中央衛生主管機關所公告實施之「全民健康保險保險對象免自行負擔費用辦法」規定，取得全民健康保險保險人核發之重大傷病證明者，該證明文'),
  ('fubon', '富邦人壽卡好康重大傷病終身健康保險', 2, '特定重大傷病', '特定重大傷病保險金', '保額 × 10%', '第十四條被保險人於本契約第二保單年度起之有效期間內，經醫院醫師診斷，確認首次罹患第二條約定之重大傷病之一，而得受領第十三條約定之「重大傷病保險金」，且該項重大傷病亦同時符合第二條約定之「特定重大傷病」者，本公司除給付「重大傷病保險金」外，另按罹患特定重大傷病時之保險金額的10%給付「特定重大傷病保險金」後，本契約效力即行終止。'),
  ('fubon', '富邦人壽卡好康重大傷病終身健康保險', 3, '生存', '生存保險金', '依已繳保費計算（看原文）', '第十五條本契約有效期間內，被保險人在第二十五保單年度屆滿時仍生存，且未致成附表三所列完全失能程度之一及未重大傷病診斷確定者，本公司於第二十五保單年度屆滿時按年繳保險費總和的10%給付「生存保險金」。'),
  ('fubon', '富邦人壽卡好康重大傷病終身健康保險', 4, '身故', '身故保險金', NULL, '第十六條被保險人於本契約有效期間內身故者，本公司按下表約定給付「身故保險金」後，本契約效力即行終止：保單年度給付金額按下列二者之最大值給付：第1保單年度一、身故時之當年度保險金額。'),
  ('fubon', '富邦人壽卡好康重大傷病終身健康保險', 5, '完全失能', '完全失能保險金', NULL, '第十七條被保險人於本契約有效期間內致成附表三所列完全失能程度之一者，本公司按下表約定給付「完全失能保險金」後，本契約效力即行終止：保單年度給付金額按下列二者之最大值給付：第1保單年度一、完全失能診斷確定時之當年度保險金額。'),
  ('fubon', '富邦人壽卡好康重大傷病終身健康保險', 6, '祝壽', '祝壽保險金', NULL, '第十九條被保險人於本契約有效期間內且在保險年齡屆滿一百歲仍生存者，本公司按保險年齡屆滿一百歲時之當年度保險金額給付「祝壽保險金」後，本契約效力即行終止。'),
  ('fubon', '富邦人壽優卡安心重大傷病健康保險', 1, '重大傷病', '重大傷病保險金', NULL, '第十四條被保險人於等待期間屆滿後或復效日起之本契約有效期間內，經醫院醫師診斷，確認首次罹患第二條約定重大傷病範圍所列傷病之一，且符合下列兩項情形之一者，本公司按下表約定給付「重大傷病保險金」後，本契約效力即行終止：一、已依中央衛生主管機關所公告實施之「全民健康保險保險對象免自行負擔費用辦法」規定，取得全民健康保險保險人核發之重大傷病證明者，該證明文'),
  ('fubon', '富邦人壽優卡安心重大傷病健康保險', 2, '特定重大傷病', '特定重大傷病保險金', '保額 × 20%', '第十五條被保險人於本契約第二保單年度起之有效期間內，經醫院醫師診斷，確認首次罹患第二條約定之重大傷病之一，而得受領第十四條約定之「重大傷病保險金」，且該項重大傷病亦同時符合第二條約定之「特定重大傷病」者，本公司除給付「重大傷病保險金」外，另按罹患特定重大傷病時之保險金額的20％給付「特定重大傷病保險金」後，本契約效力即行終止。'),
  ('fubon', '富邦人壽優卡安心重大傷病健康保險', 3, '特定重大疾病', '特定重大疾病保險金', '取較高：保額 × 1／保費 × 1.06', '第十六條被保險人於等待期間屆滿後或復效日起之本契約有效期間內，經醫院醫師診斷，確認罹患第二條約定特定重大疾病項目之一者，本公司按下列二者之最大值給付「特定重大疾病保險金」後，本契約效力即行終止：一、罹患特定重大疾病時之保險金額。二、年繳保險費總和之一點零六倍。被保險人於本契約有效期間內，不論同時或先後罹患二項特定重大疾病，本公司僅對其中一項特定重大疾病負給付「特定重大疾病保險金」之責任。若係同項特定重大疾病發生二次以上者，本公司僅對其中一次特定重大疾病負給付「特定重大疾病保險金」之責任。【保險範圍：特定傷病保險金的給付】第十七條被保險人於等待期間屆滿後或復效日起之本契約有效期間內，經醫院醫師診斷，確認罹患第二條約定特定傷病項目之一者，本公司按下列二者之最大值給付「特定傷病保險金」後'),
  ('fubon', '富邦人壽優卡安心重大傷病健康保險', 4, '特定傷病', '特定傷病保險金', '取較高：保額 × 1／保費 × 1.06', '第十七條被保險人於等待期間屆滿後或復效日起之本契約有效期間內，經醫院醫師診斷，確認罹患第二條約定特定傷病項目之一者，本公司按下列二者之最大值給付「特定傷病保險金」後，本契約效力即行終止：一、罹患特定傷病時之保險金額。二、年繳保險費總和之一點零六倍。被保險人於本契約有效期間內，不論同時或先後罹患二項特定傷病，本公司僅對其中一項特定傷病負給付「特定傷病保險金」之責任。若係同項特定傷病發生二次以上者，本公司僅對其中一次特定傷病負給付「特定傷病保險金」之責任。【分期定期保險金給付】第十八條本契約有保險金分期定期給付之指定者，自分期定期給付開始日及分期定期給付開始日之每一週月日，本公司依分期定期保險金給付期間及第二條定義之分期定期保險金預定利率將指定保險金換算成每月初應給付之金額，按'),
  ('fubon', '富邦人壽優卡安心重大傷病健康保險', 5, '完全失能', '完全失能保險金', '取較高：保費 × 1.06／保額 × 1', '第二十條被保險人於本契約有效期間內致成附表二所列完全失能程度之一者，本公司按下列二者之最大值給付「完全失能保險金」後，本契約效力即行終止：一、年繳保險費總和之一點零六倍。二、完全失能診斷確定時之保險金額。【保險範圍：滿期保險金的給付】第二十一條被保險人於本契約有效期間內且在保險年齡屆滿八十四歲仍生存者，本公司按下列二者之最大值給付「滿期保險金」後，本契約效力即行終止：一、年繳保險費總和之一點零六倍。二、保險年齡屆滿八十四歲時之保險金額。【保險範圍：二至六級意外失能豁免保險費】第二十二條被保險人於本契約有效且繳費期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成附表三所列二至六級失能程度之一者，經醫院'),
  ('fubon', '富邦人壽優卡安心重大傷病健康保險', 6, '滿期', '滿期保險金', '取較高：保費 × 1.06／保額 × 1', '第二十一條被保險人於本契約有效期間內且在保險年齡屆滿八十四歲仍生存者，本公司按下列二者之最大值給付「滿期保險金」後，本契約效力即行終止：一、年繳保險費總和之一點零六倍。二、保險年齡屆滿八十四歲時之保險金額。【保險範圍：二至六級意外失能豁免保險費】第二十二條被保險人於本契約有效且繳費期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成附表三所列二至六級失能程度之一者，經醫院醫師診斷確定，本公司豁免失能診斷確定日後本契約（不含附約）續期應繳之各期保險費，本契約繼續有效。但超過一百八十日致成二至六級失能程度之一者，受益人若能證明被保險人之失能與該意外傷害事故具有因果關係者，不在此限。被保險人因本次意外傷害'),
  ('fubon', '富邦人壽優卡安心重大傷病健康保險', 7, '身故', '身故保險金或喪葬費用保險金', NULL, '第三十四條有下列情形之一者，本公司不負給付「身故保險金或喪葬費用保險金」及「完全失能保險金」的責任：一、要保人故意致被保險人於死。'),
  ('fubon', '富邦人壽鍾心御守重大傷病健康保險', 1, '重大傷病', '重大傷病保險金', NULL, '第十四條被保險人於等待期間屆滿後或復效日起之本契約有效期間內，經醫院醫師診斷，確認首次罹患第二條約定重大傷病範圍所列傷病之一，且符合下列兩項情形之一者，本公司按下表約定給付「重大傷病保險金」後，本契約效力即行終止：一、已依中央衛生主管機關所公告實施之「全民健康保險保險對象免自行負擔費用辦法」規定，取得全民健康保險保險人核發之重大傷病證明者，該證明文'),
